The \emph{Conditional Stochastic Optimization} (CSO) problem is formulated as follows:
\begin{equation}
\min_{\beta \in {\Bb}} G(\beta) \triangleq \Eb \Big\{g\big(\Eb [f(X,Y,\beta) \,|\, X]\big)\Big\}
\label{cso}
\end{equation}

where $\Bb \subset \Rb^{n_\beta}$, $f: \Rb^{n_X} \times \Rb^{n_Y} \times \Rb^{n_\beta} \to \Rb^{n_f}$ , and $g: \Rb^{n_f} \to \Rb$. In formula \eqref{cso}, $X$ and $Y$ are random variables, and the symbols $\Eb[\Cdot]$ and $\Eb[\Cdot|X]$ represent the expected value and the conditional expected value, respectively.


\begin{equation}
    \label{def:F}
F(X, \beta) \triangleq \Eb[f(X, Y, \beta) | X].
\end{equation}

We assume that a sufficiently rich class of functions $\varPsi: \Rb^{n_x} \times \Rb^{n_\theta} \to \Rb^{n_f}$ has been established,
such that for every
$\beta\in {\Bb}$ an (unknown) value of the parameters $\bar{\theta}(\beta) \in \Rb^{n_\theta}$ exists for which
\begin{equation}
\label{tracking-exact}
F(X,\beta) = \varPsi\big(X,\bar{\theta}(\beta)\big)  \quad \text{a.s.}
\end{equation}

\begin{equation}
Q(\beta, \theta) \triangleq \frac{1}{2}
\Eb\big[\|F(X, \beta) - \varPsi(X, \theta)\|^2\big],
\label{te:Q}
\end{equation}

Below we review some notation and conventions used throughout the paper. For simplicity, we ignore all the arguments of the functions,
if they are obvious from the context. We also indicate generalized derivatives in the subscript of a function symbol,
that is, $F_x(\Cdot) \in \partial F(\Cdot)$.  We only use the $l_2$-norm in this paper, which is denoted as $\|\Cdot\|$. A dot
over a symbol, for example, $\dt{F}$, represents the generalized derivative of $F(\beta(t))$ with respect to the
time variable, where $\beta(t)$ is an absolutely continuous path (usually, evident from the context).
A function $g: \Rb^n \to \Rb^m$ is \emph{$L$-Lipschitz continuous} if $L > 0$ exists  such that $\|g(x) - g(y)\| \le L \|x-y\|$ for all $x, y \in \Rb^n$. A differentiable function $g: \Rb^n \to \Rb^m$ is called \emph{$L$-Lipschitz smooth} if the vector function $\nabla g(\Cdot)$ is \emph{$L$-Lipschitz continuous}. This implies that $\|g(x) - g(y) - \nabla g(y)^T (x - y)\| \le \frac{L}{2} \|x-y\|^2$ for all $x, y \in \Xc$. A differentiable function $g: \Xc \to \Rb$ is
\emph{strongly convex with modulus $L>0$} if $g(x) - g(y) - \nabla g(y)^T (x - y) \ge \frac{L}{2} \|x-y\|^2$ for all $x, y \in \Xc$. It is \emph{weakly convex with modulus $L$} if
$g(x) - g(y) - \nabla g(y)^T (x - y) \ge -\frac{L}{2} \|x-y\|^2$ for all $x, y \in \Xc$.
An $L$-Lipschitz smooth function is $L$-weakly convex.


\begin{description}
\item[(A1)] The set $\Bb$ is convex and compact.
\item[(A2)] The function $g(\Cdot)$ is continuously differentiable, its gradient is differentiable in the generalized sense, and constants $L_g$ and ${L_{\nabla g}}$ exist,
such that $\| \nabla g(u)\| \le L_g$ and $\| \nabla g(u) - \nabla g(v)\| \le {L_{\nabla g}}\|u -v\|$ for all $u,v \in \Rb^{n_f}$.
\item[(A3)] For every $x \in \Rb^{n_x}$ and every $y\in \Rb^{n_y}$ the function $f(x,y,\Cdot)$ is differentiable in the generalized sense
with the generalized subdifferential $\hat{\partial} f(x,y,\Cdot)$. Furthermore,  a function ${L_f}(x,y)$ and  constants $\widebar{L}_f>0$ and $C_f>0$  exist, such that
for all $\beta\in \Bb$ and all $(x,y)$
\begin{gather*}
 \sup_{f_\beta \in \hat{\partial} f(x,y,\beta)}\|f_\beta\| \le {L_f}(x,y),\\
\Eb [ {L_f}(X,Y)^4 ] \le \widebar{L}_f^4,\\
\intertext{and}
\Eb\big[\|f(X,Y,\beta)\|^4 \big] \le C_f^4.
\end{gather*}


\item[(A4)] For every $x \in \Rb^{n_x}$ the function $\varPsi(x,\Cdot)$ is differentiable in the generalized sense
with the generalized subdifferential $\hat{\partial} \varPsi(x,\Cdot)$. Furthermore, a function ${L_\psi}(x)$ and  constants
$\widebar{L}_\varPsi>0$ and  $C_{\varPsi}>0$ exist, such that for all $x$
\begin{gather*}
\sup_{\theta \in \Rb^{n_\theta}}\  \sup_{\varPsi_\theta \in \hat{\partial} \varPsi(x,\theta)}\|\varPsi_\theta\| \le {L_\psi}(x),\\
\Eb [ {L_\psi}(X)^4 ] \le \widebar{L}_\varPsi^4,\\
\intertext{and for some $\theta^0$,}
\Eb [ \|\varPsi(X,\theta^0)\|^4 ] \le C_\varPsi^4.
\end{gather*}
\end{description}


We can compactly write the assertion of the above lemma as\footnote{Here and elsewhere, the subdifferentiation is with respect to the parameters $\beta$ or $\theta$; we omit the corresponding subscripts of $\hat{\partial}$ to alleviate the notation.}
\begin{equation}
\label{dFbeta}
\hat{\partial}_{  \beta} F(X,\beta) = \Eb \big[ \hat{\partial}_{  \beta} f(X,Y,\beta)\,\big|\, X \big] \quad \text{a.s.,}
\end{equation}

where the conditional expectation on the right-hand side is understood as the collection of conditional expected values of all measurable selections of the multifunction
$(X,Y) \mapsto \hat{\partial}_{  \beta} f(X,Y,\beta)$.


As mentioned before, for every $\beta \in {\Bb}$, a parameter value $\bar{\theta}(\beta)\in \Rb^{n_\theta}$ exists,
such that $Q\big(\beta,\bar{\theta}(\beta)\big)=0$. In addition to that, we assume the following
growth condition.
\begin{description}
\item[(A5)] A constant $M>0$ exists such that for all $\beta\in {\Bb}$ and all $\theta \in \Rb^{n_\theta}$
\[
 Q(\beta,\theta)  \le M \big[\dist\big(0,\hat{\partial}_{\theta} Q(\beta,\theta)\big)\big]^2.
\]
\end{description}


Finally, we need an assumption about the behavior of the tracking error for very large $\theta$.

\begin{description}
\item[(A6)] A constant $\underline{R}>0$ exists such that if $\beta\in {\Bb}$ and  $\|\theta\|\ge \underline{R}$, then for all $Q_\theta \in\hat{\partial}_{\theta} Q(\beta,\theta)  $,
\[
\langle \theta, Q_\theta \rangle >0.
\]
\end{description}


The necessary optimality condition  for problem \eqref{cso} has the form
\begin{equation}
\label{optimality}
0 \in \hat{\partial}_{ \beta} G(\beta) + \Nc_{\Bb}(\beta),
\end{equation}

where $\hat{\partial}_{ \beta} G(\Cdot)$ is the generalized subdifferential \eqref{G-sub} and $\Nc_{\Bb}(\Cdot)$ is the normal cone
to the set $\Bb$. We define the sets
\begin{align*}
    {\Bb}^* &= \big\{ \beta\in {\Bb} : \ \text{\eqref{optimality} is satisfied} \big\},\\
    \Zb^* &= \big\{ (\beta,\theta)\in {\Bb}^* \times \Rb^{n_\theta}:  Q(\beta,\theta) = 0\big\}.
\end{align*}

We propose a stochastic subgradient method for finding an element of $\Zb^*$.


To simplify the development and analysis
of the method, we assume that $R \ge \underline{R}$ is known,
so that $\Zb^* \subset \Bb \times \Theta_R$,
where $\Theta_R = \{ \theta\in \Rb^{n_\theta}: \|\theta \| \le R\}$.
Due to Assumption (A6), any $R\ge \underline{R}$ has this property.

At each iteration $k=0,1,\dots$ of the method,
given the current approximate solution $(\beta^k,\theta^k)\in {\Bb} \times \Theta_R$,
we use an observation $(X^k,Y^k)$ from the joint distribution of $(X,Y)$, to construct random directions
$\tilde{d}_\beta^k$ and $\tilde{d}_\theta^k$, and to update the current point:
\begin{equation}
\label{method}
\begin{aligned}
\beta^{k+1} &= \varPi_{\Bb}(\beta^k + \tau_k \tilde{d}_\beta^k),\\
\theta^{k+1} &= \varPi_{\Theta_R}(\theta^k + \tau_k \tilde{d}_\theta^k).
\end{aligned}
\end{equation}

Here, $\tau_k>0$ is a stepsize of the method, $\varPi_{\Bb}(\Cdot)$  denotes the orthogonal projection on $\Bb$,
and $\varPi_{\Theta_R}(\Cdot)$ is the orthogonal projection on the ball $\Theta_R$.

To construct the directions $\tilde{d}_\beta^k$ and $\tilde{d}_\theta^k$,
we use the values and  generalized gradients of the functions $f(X^k,Y^k,\Cdot)$ and $\varPsi(X^k,\Cdot)$, which
can be observed at the current point $(\beta^k,\theta^k)$. We also use the derivatives of the function $g(\Cdot)$ at the
points $\varPsi(X^k,\theta^k)$, which can be observed as well.

In our presentation of the method and its analysis, we denote by $(\varOmega,\Fc,P)$ the algorithmic probability space on which
the random sequences generated by the method are defined, and by
$\Fc_k$ the $\sigma$-subalgebra defined by the history $(\beta^0,\theta^0,X^0,Y^0,\dots,X^{k-1},Y^{k-1},\beta^k,\theta^k)$.
We assume that at iteration $k=0,1,\dots$ we observe the pair $(X^k,Y^k)$, independently of $\Fc_k$, and we calculate the following quantitites:
\begin{gather*}
f^k  = f(X^k,Y^k,\beta^k),\\
f_\beta^k  \in \hat{\partial}_{ \beta} f(X^k,Y^k,\beta^k),\\
\varPsi^k  = \varPsi(X^k,\theta^k),\\
\varPsi_\theta^k  \in \hat{\partial}_{ \theta} \varPsi(X^k,\theta^k),\\
\nabla g^k = \nabla g(\varPsi^k).
%\\
%{  \nabla^2 g^k \in \hat{\partial} \nabla g(\varPsi^k).}
\end{gather*}

Then we calculate the directions in \eqref{method}:
\begin{subequations}
\label{dzk}
\begin{align}
    \tilde{d}_\beta^k &= - f_\beta^k \,\nabla g^k,  \label{dbetak}\\
    \tilde{d}_\theta^k &=\gamma \,\varPsi_\theta^k (f^k - \varPsi^k). \label{dthetak}
\end{align}

\end{subequations}
Here, $\gamma>0$ is a parameter of the method.


\begin{description}
\item[(A7)]
The stepsizes $\tau_k$ are $\Fc_k$-measurable, and such that\vspace{0.5ex}
\begin{tightlist}{iii}
\item  $\tau_k >0, \quad k=0,1,2,\dots$;
\item   $ \displaystyle{\sum_{k=0}^\infty} \tau_k = \infty \quad \text{a.s.}$;
\item $\Eb \displaystyle{\sum_{k=0}^\infty} \tau_k^2 < \infty$.
\end{tightlist}
\end{description}


Consider the multifunction
$\varGamma: \Bb \times \Theta_R \rightrightarrows \Rb^{n_f}$ defined as follows:
\[
\varGamma(\beta,\theta) = \Eb
\left\{
\begin{bmatrix}
 -\hat{\partial}_\beta F(X,\beta) \nabla g\big(\varPsi(X,\theta)\big) \\
\gamma \,\hat{\partial}_\theta \varPsi(X,\theta)\big(F(X,\beta) -\varPsi(X,\theta)\big)
\end{bmatrix}
\right\}.
\]

We need to establish the properties of the multifunction $\varGamma(\Cdot,\Cdot)$ that are relevant for the convergence analysis.


Define the average directions,
\begin{equation}
\label{def:avg_dir}
d^k = \Eb [\tilde{d}^k \,| \, \Fc_k],\quad k=0,1,\dots,
\end{equation}

and let
\begin{equation}
\notag
%\label{def:e}
e^k = \tilde{d^k} - d^k.
\end{equation}

For brevity, denote $z^k = (\beta^k,\theta^k) $, $k=0,1,\dots$, and $\Zb=\Bb \times\Theta_R$.
We consider a particular trajectory $z^k(\omega) = (\beta^k(\omega),\theta^k(\omega)) $, $k=0,1,\dots$; in our notation, we omit
the elementary event $\omega\in \Omega$, which may be arbitrary, except for a zero measure set.

First, we construct continuous-time trajectories by linear interpolation. We introduce the accumulated stepsizes
\[
t_k = \sum_{j=0}^{k-1}\tau_j,\quad k=0,1,\dots,
\]

and we construct the interpolated trajectory
\[
Z_0(t) = z^k + \frac{t-t_{k}}{\tau_k}(z^{k+1}-z^k),\quad t_{k}\le t \le t_{k+1},\quad k=0,1,\dots.
\]

Then, for an increasing sequence of positive numbers $\{s_m\}$ diverging to $\infty$, we define the shifted trajectories
\begin{equation}
\label{Z-shifted}
Z_m(t)=Z_0(t+s_m), \quad m=0,1,\dots,\quad t \ge 0.
\end{equation}

In particular, if we set $s_m = t_m$, we obtain $Z_m(0) = z^m$.


To this end, we construct a specially tailored Lyapunov function with parameters $\alpha > 0$ and $\lambda \ge 0$:
\begin{equation}
\label{Lyapunov}
    w(\beta,\theta) \triangleq G(\beta) + \alpha \Delta^\lambda(\beta, \theta),
\end{equation}

where $G(\beta)$ is the CSO loss function in \eqref{cso} and
\begin{equation}
\Delta^{\lambda}(\beta,\theta) \triangleq \Eb\Big[g(F) - g(\varPsi) - \langle \nabla g(\varPsi), F - \varPsi \rangle + \frac{\lambda}{2} \|F-\varPsi\|^2\Big].
\label{te:g}
\end{equation}

In order to prove the convergence of the discrete-time algorithm, we need an additional technical assumption (known as the \emph{Sard condition}).
\begin{description}
\item[(A8)] The set $\{G(\beta): \beta\in {\Bb}^*\}$ does not contain an interval of nonzero length.
\end{description}


\begin{definition}
\label{d:Norkin}
A function $f:\Rb^n\to\Rb$ is  \emph{differentiable in a generalized sense at a point} $x\in \Rb^n$,
if an open set $U\subset \Rb^n$ containing $x$,
and a nonempty, convex, compact valued, and upper semicontinuous multifunction
$\hat{\partial}f: U \rightrightarrows \Rb^n$ exist, such that for all $y\in U$ and all $g \in \hat{\partial}f(y)$ the following equation is true:
\[
f(y) = f(x) + \langle g(y), y-x \rangle + o(x,y,g),
\]
with
\[
\lim_{y\to x} \sup_{g\in \hat{\partial}f(y)} \frac{o(x,y,g)}{\|y-x\|}=0.
\]
The set $\hat{\partial}f(y)$ is  the \emph{generalized subdifferential} of $f$ at $y$.
If a function is differentiable in a generalized sense at every  $x \in \Rb^n$ with the same generalized subdifferential mapping $\hat{\partial}f:\Rb^n\rightrightarrows \Rb^n$, we call it \emph{differentiable in a generalized sense}.

A function $f:\Rb^n\to\Rb^m$ is  differentiable in a generalized sense, if each of its component functions, $f_i:\Rb^n\to\Rb$, $i=1,\dots,m$, has this property.
\end{definition}

