\begin{theorem}
    \label{t:full-convergence}
    Assume conditions {\rm (A1)--(A8)} and \eqref{negative-der}. Then, except for a zero measure set $\varOmega_0\subset \varOmega$,  the sequence $\big\{w(z^k(\omega))\big\}_{k\in \Nb}$ is convergent, and every accumulation point of the sequence
$\big\{z^k(\omega)\big\}_{k\in \Nb}$ is an element of $\Zb^*$.
\end{theorem}

