proof.raw_tex:
\begin{lemma}
\label{l:conditional_subgradient}
Suppose the function $f(X,Y,\Cdot)$ is differentiable in the generalized sense and its subgradients are bounded
by an integrable function in any bounded neighborhood of any point $\beta$. Then for almost all $X$ the function
$\beta \mapsto \Eb\big[ f(X,Y,\beta) \big| X\big]$ is differentiable in the generalized sense, and
for every measurable function $s:\Rb^{n_x}\times \Rb^{n_y} \to \Rb^{n_f}$ such that $s(X,Y)  \in \hat{\partial}_\beta f(X,Y,\beta)$ a.s., we have
\[
\Eb\big[s(X,Y) \big| X\big] \in \hat{\partial} \Eb\big[ f(X,Y,\beta) \big| X\big] \quad  a.s.
\]
\end{lemma}

\begin{proof}
The probability measure $P$ on $\Rb^{n_x}\times \Rb^{n_y}$
can be disintegrated into a marginal measure $P_X$ on $\Rb^{n_x}$ and a kernel $T:\Rb^{n_x} \to \Pc(\Rb^{n_y})$,
 where $\Pc(\Rb^{n_y})$ is the space of probability measures
 on $\Rb^{n_y}$. Then
\[
\Eb\big[ f(X,Y,\beta) \big| X=x\big] = \int f(x,y,\beta)\;T(\D y|x).
\]
For every bounded neighborhood $K$ of $\beta$, the Lipschitz constant $L_K(x,y)$ of the function $f(x,y,\Cdot)$
is integrable, and thus, for almost
all $x$, its conditional expectation
$\int L_K(x,y)\,T(dy|x)$ exists as well.
The assertion then follows from Theorem \ref{t:expected-generalized}.
\end{proof}

Furthermore, by Theorem \ref{t:composition} and Assumption (A2), the composition
$g( F(x,\Cdot))$ is differentiable in the generalized sense as well, and
\[
\hat{\partial}_{  \beta} [g\circ F](x,\beta)  = \big\{    F_\beta(x,\beta) \nabla g(F(x,\beta)) : F_\beta(x,\beta) \in \hat{\partial}_{  \beta} F (x,\beta)\big\}
\]
is its generalized subdifferential (we adopt the convention that the generalized Jacobian $F_\beta$ is an $n_\beta \times n_f$ matrix).
Thanks to the integrability condition in (A3) and Theorem \ref{t:expected-generalized}, the function $G(\Cdot)$ in \eqref{cso}
is differentiable in the generalized sense as well, and a realization of its generalized subdifferential is the multifunction
\begin{equation}
    \label{G-sub}
\begin{aligned}
\hat{\partial}_{  \beta} G(\beta) &= \Eb \big\{ \hat{\partial}_{  \beta} [g\circ F](X,\beta) \big\}
=\Eb \big\{
\hat{\partial}_{  \beta} F (X,\beta) \nabla g(F(X,\beta))
\big\}
\\ &= \Eb \big\{
\hat{\partial}f (X,Y,\beta) \nabla g(F(X,\beta))
\big\}.
\end{aligned}
\end{equation}
The last equation follows by conditioning.


Due to Assumptions (A3) and (A4), by virtue of Theorem \ref{t:composition},
the error function \eqref{te:Q} is differentiable in the generalized sense as well, and
the multifunction
\begin{equation}
\label{dQ}
\hat{\partial}_{(\beta,\theta)} Q(\beta,\theta) =
\Eb\left\{ \begin{bmatrix}
\hat{\partial}_{  \beta} f(X,Y,\beta) \\
-\hat{\partial}_{  \theta} \varPsi(X,\theta)
\end{bmatrix}
 \big(   F(X, \beta) - \varPsi(X, \theta)\big) \right\}
\end{equation}
is its generalized subdifferential.
%Evidently, we cannot observe unbiased estimates of the subgradients of $Q(\Cdot,\Cdot)$, because we do not see $F(X,\beta)$.
Since the set \eqref{dQ} is a Cartesian product, its $\theta$-part,
\[
\hat{\partial}_{\theta} Q(\beta,\theta) =
- \Eb\left\{
\hat{\partial}_{  \theta} \varPsi(X,\theta)
 \big(   F(X, \beta) - \varPsi(X, \theta)\big) \right\},
\]
is a subdifferential of $Q(\beta,\theta)$ with respect to $\theta$.


\begin{lemma}
\label{l:Gamma}
The multifunction $\varGamma(\Cdot,\Cdot)$ is nonempty-, convex-, and compact-valued and upper-semicontinuous.
\end{lemma}

\begin{proof}
By virtue of Lemma \ref{l:conditional_subgradient}, the $\beta$-component of $\varGamma(\beta,\theta)$ equals
\begin{multline*}
 -\Eb \big[ \hat{\partial}_\beta F(X,\beta) \nabla g\big(\varPsi(X,\theta)\big)\big] =
 -\Eb\Big\{ \Eb\big[ \hat{\partial}_\beta f(X,Y,\beta)\big|X\big] \nabla g\big(\varPsi(X,\theta)\big)\Big\}\\
% - \hat{\partial}_\beta  \Eb \big[ F(X,\beta) \nabla g\big(\varPsi(X,\theta)\big)\big]\\
% =
% - \hat{\partial}_\beta  \Eb \big[ f(X,Y,\beta) \nabla g\big(\varPsi(X,\theta)\big)\big]
  =
 - \Eb \big[ \hat{\partial}_\beta  f(X,Y,\beta) \nabla g\big(\varPsi(X,\theta)\big)\big].
\end{multline*}
\begin{comment}
The interchange of the subdifferentiation and the expected value is justified because
Assumptions (A2) and (A3) imply that:
\begin{tightlist}{ii}
\item the function
$\beta \mapsto f(X,Y,\beta) \nabla g\big(\varPsi(X,\theta)\big)$ is
Norkin differentiable; and
\item its Lipschitz constant $L_f(X,Y) L_g$ is integrable.
\end{tightlist}
\vspace{0.5ex}
\end{comment}

The $\theta$-component of $\varGamma(\beta,\theta)$ can be written as follows:
\[
\gamma \,\Eb \big[ \hat{\partial}_\theta \varPsi(X,\theta)\big(F(X,\beta) -\varPsi(X,\theta)\big)\big]
= \gamma \,\Eb \big[ \hat{\partial}_\theta \varPsi(X,\theta)\big(f(X,Y,\beta) -\varPsi(X,\theta)\big)\big].
\]
Due to Assumptions (A2)--(A4), for all $(X,Y)$, the multifunction
\[
(\beta,\theta) \mapsto \widetilde{\varGamma}(\beta,\theta;X,Y) \triangleq
\begin{bmatrix}
 -\hat{\partial}_{ \beta} f(X,Y,\beta) \nabla g\big(\varPsi(X,\theta)\big) \\
\gamma \,\hat{\partial}_{ \theta} \varPsi(X,\theta)\big(f(X,Y,\beta) -\varPsi(X,\theta)\big)
\end{bmatrix}
\]
is upper-semicontinuous, and convex- and compact-valued. Furthermore, its $\beta$-values are
bounded by and integrable function $L_f(X,Y)L_g$, and its $\theta$-values are bounded
by an integrable function $  \gamma L_{\varPsi}(X)( C_f +  C_{\varPsi} + 4  L_{\varPsi}(X) R^2)$.
These two conditions imply that its integral -- the multifunction $\varGamma(\Cdot,\Cdot)$ -- is upper-semicontinuous, and convex- and compact-valued as well. This implication is part of
the proof of Theorem \ref{t:expected-generalized}; see \cite[Lem. 21.7]{mikhalevich1987nonconvex}.
\end{proof}

\begin{lemma}
\label{l:dk-in-Gamma}
For all $k=0,1,2,\dots$ we have $d^k \in \varGamma(\beta^k,\theta^k)$.
\end{lemma}

\begin{proof}
Since the observation $(X^k,Y^k)$ is independent of $\Fc_k$, Lemma \ref{l:conditional_subgradient}  yields the relations
\begin{align*}
\Eb[\tilde{d}_\beta^k|\Fc_k]  &\in -\Eb \big[ \hat{\partial}_{ \beta} f(X^k,Y^k,\beta^k) \nabla g(\varPsi(X^k,\theta^k)) ~\big|~ \Fc_k\big] \\
&= -\Eb \Big\{ \Eb \big[ \hat{\partial}_{ \beta} f(X^k,Y^k,\beta^k)  ~\big|~ \beta^k,\theta^k, X^k \big] \nabla g(\varPsi(X^k,\theta^k)) ~\Big|~ \beta^k,\theta^k \Big\}\\
&= -\Eb \big[ \hat{\partial}_{ \beta} F(X^k,\beta^k) \nabla g(\varPsi(X^k,\theta^k)) ~\big|~ \beta^k,\theta^k \big]
= \varGamma_\beta (\beta^k,\theta^k).
\end{align*}
The $\theta$-component of the direction can also be treated by conditioning:
\begin{align*}
\Eb[\tilde{d}_\theta^k|\Fc_k] &\in \gamma \Eb \big[ \hat{\partial}_{ \theta} \varPsi(X^k,\theta^k)\big(f(X^k,Y^k,\beta^k) -\varPsi(X^k,\theta^k)\big)\big| \Fc_k\big]\\
&= \gamma \Eb \Big\{\hat{\partial}_{ \theta} \varPsi(X^k,\theta^k)\Eb\big[f(X^k,Y^k,\beta^k) -\varPsi(X^k,\theta^k)\big| X^k,\beta^k,\theta^k\big]\Big| \beta^k,\theta^k\Big\}\\
&= \gamma \Eb \big\{\hat{\partial}_{ \theta} \varPsi(X^k,\theta^k)\big(F(X^k,\beta^k) -\varPsi(X^k,\theta^k)\big)\big| \beta^k,\theta^k\big\} = \varGamma_\theta(\beta^k,\theta^k).
\end{align*}
\end{proof}

\begin{lemma}
    \label{l:e2-bounded}
Under Assumptions \textup{(A1)--(A4)}, the directions $\{d^k\}_{k\ge 0}$ are well-defined and a constant $\sigma > 0$ exists, such that
$\Eb\big[\|e^k\|^2 \,\big|\,\Fc_k\big] \le \sigma^2$, for all $k \ge 0$.
\end{lemma}

\begin{proof}
For the $\beta$-component $e_\beta^k$ of $e^k$,  we have
\[
\tilde{d}_\beta^k = -f_\beta(X^k,Y^k,\beta^k)\nabla g(\varPsi(X^k,\theta^k)),
\]
and thus, by Assumptions (A2) and (A3),
\[
\Eb\big[ \|{e}_\beta^k\|^2\big| \Fc_k ] \le \Eb\big[ \|\tilde{d}_\beta^k\|^2\big| \Fc_k ]
\le L_g^2 \Eb \big[ \| f_\beta(X^k,Y^k,\beta^k)\|^2 \big| \Fc_k \big]\le
 L_g^2 \widebar{L}_f^2.
\]
For the $\theta$-component,
\begin{align*}
\Eb\big[ \| \tilde{d}_\theta^k\|^2\big| \Fc_k\big]
&\le \gamma^2 \Eb\big[ \|\varPsi_\theta(X^k,\theta^k)\|^2 \cdot \| f(X^k,Y^k,\beta^k)  - \varPsi(X^k,\theta^k)\|^2\big| \Fc_k\big]\\
&\le \gamma^2 \Eb\big[{L_\psi}(X^k)^2\| f(X^k,Y^k,\beta^k)  - \varPsi(X^k,\theta^k)\|^2\big| \Fc_k\big]\\
&\le 2\gamma^2 \Eb\big[{L_\psi}(X^k)^2\| f(X^k,Y^k,\beta^k)\|^2\big| \Fc_k\big]\\
&{\quad} +2 \gamma^2 \Eb\big[ {L_\psi}(X^k)^2\|\varPsi(X^k,\theta^k)\|^2\big| \Fc_k\big].
\end{align*}
Using the Cauchy--Schwartz inequality and Assumptions (A3) and (A4) we obtain
\[
\Eb\big[{L_\psi}(X^k)^2\| f(X^k,Y^k,\beta^k)\|^2\big| \Fc_k\big]
\le  \widebar{L}_\varPsi^2 C_f^2.
\]
In a similar way, by (A4),
\begin{align*}
\lefteqn{\Eb\big[ {L_\psi}(X^k)^2\|\varPsi(X^k,\theta^k)\|^2\big| \Fc_k\big]}\\
&\le 2 \Eb\big[{L_\psi}(X^k)^2\big( \|\varPsi(X^k,\theta^0)\|^2 + {L_\psi}(X^k)^2 \|\theta^k-\theta^0\|^2\big)\big| \Fc_k\big]
\le 2 \widebar{L}_\varPsi^2 C_\varPsi^2 + 8R^2 \widebar{L}_\varPsi^4.
\end{align*}
Combining the last three inequalities, we conclude that
$\Eb\big[ \| e_\theta^k\|^2\big| \Fc_k\big] $, $k\ge 0$, are uniformly bounded as well.
\end{proof}

The following theorem follows directly from \cite[Thm. 4.1]{majewski2018analysis}.
\begin{theorem}
\label{t:diff-inc-beta}
Under Assumptions \textup{(A1)--(A4)} and \textup{(A7)},
the sequence $\big\{Z_m(\Cdot)\big\}_{m\ge 0}$ has a subsequence convergent a.s. to an absolutely continuous function $Z_\infty:[0,\infty) \to \Xc$ which is a solution of the differential inclusion:
\begin{equation}
\label{diff-inc-beta}
\dt{Z}_\infty(t) \in  \varGamma(Z_{\infty}(t))-\Nc_{\Zb}(Z_\infty(t)), \quad t \ge 0.
\end{equation}
Moreover, for any $t\ge 0$, the point $Z_\infty(t)$
is an accumulation point of the sequence $\{z^k\}_{k\ge 0}$.
\end{theorem}

Since any solution of \eqref{diff-inc-beta} must lie in $\Zb$,
we can  write the differential inclusion \eqref{diff-inc-beta} in an equivalent way \cite{aubin2012differential}:
\begin{equation}
\label{diff-inc-beta-T}
\dt{Z}_\infty(t) \in \varPi_{\Tc_{\Zb}(Z_\infty(t))}\big( \varGamma(Z_\infty(t))\big), \quad t \ge 0,
\end{equation}
which underlines the nature of the limiting subgradient process. Here, $\Tc_\Zb(z)$ is the tangent cone to the convex set $\Zb$ at $z$.


\begin{lemma}
\label{l:w-gendif}
Under Assumptions \textup{(A2)--(A4)} the Lyapunov function $w(\Cdot,\Cdot)$ is differentiable in the generalized sense.
\end{lemma}

\begin{proof}
In \S \ref{s:2} we established the generalized differentiability of the functions $G(\Cdot)$ and $Q(\Cdot,\Cdot)$.  It remains to consider the function
\[
\Delta^{0}(\beta,\theta) = \Eb\Big[g(F) - g(\varPsi) - \langle \nabla g(\varPsi), F - \varPsi \rangle \Big],
\]
and the expression under the expected value:
\begin{equation}
    \label{delta0-beta}
\delta^{0}(\beta,\theta) = g(F) - g(\varPsi) - \langle \nabla g(\varPsi), F - \varPsi \rangle.
\end{equation}
By Assumptions (A2)--(A4) and Theorem \ref{t:composition},
$\delta^{0}(\Cdot,\Cdot)$ is Norkin differentiable. Its generalized subgradients with respect to $\beta$ have the form
\[
\delta^{0}_\beta = F_\beta\big( \nabla g(F) - \nabla g(\Psi)\big),
\]
and are bounded by $2L_g\Eb[\widebar{L}_f(X,Y)|X]$. It is an integrable function,
thanks to (A2).
In a similar way, by Assumptions (A2) and (A4) and Theorem \ref{t:composition}, the generalized subgradients
with respect to $\theta$ have the form
\begin{equation}
    \label{delta0-theta}
\delta^{0}_\theta = \varPsi_\theta H(\varPsi) ( F - \Psi),
\end{equation}
 or are convex combinations of elements of this structure,
 where we denote by $H(\varPsi)$
an arbitrary element of $\hat{\partial}(\nabla g)(\varPsi)$. Thus, their norm is
bounded by $L_{\nabla g}L_\varPsi(X)\|F-\varPsi\|$. As $L_\varPsi$
and $\|F-\varPsi\|$ are square-integrable, the bound is integrable, by virtue
of the Cauchy--Schwartz inequality.  Applying Theorem \ref{t:expected-generalized},
we conclude that the expected value function $\Delta^0$ is Norkin differentiable as well.
\end{proof}

Following the differential inclusion method, consider the function $W(t) = w(\beta(t),\theta(t))$, $t \ge 0$, where $(\beta(\Cdot),\theta(\Cdot)) \triangleq Z(\Cdot)$ is a solution of the
inclusion \eqref{diff-inc-beta}.

As the Lyapunov function $w(\Cdot,\Cdot)$ is Norkin differentiable, by virtue of Theorem \ref{t:composition}, its
weak derivative can be expressed by the chain rule:
\begin{equation}
\dt{W}
= \langle w_\beta, \dt{\beta} \rangle + \langle w_\theta, \dt{\theta} \rangle
= \langle G_\beta + \alpha \Delta^\lambda_\beta, \dt{\beta} \rangle + \alpha \langle \Delta^\lambda_\theta, \dt{\theta} \rangle.
\label{grad:P}
\end{equation}
Due to Theorem \ref{t:chain}, the integral  $\int_0^T \dt{W}(t)\,\D t$ on any interval of time does not depend on the particular selections of the generalized subgradients used in this calculation.


\begin{lemma}
Under Assumptions \textup{(A2)} and \textup{(A4)},  $\big|\langle \Delta^0_\theta, Q_\theta \rangle \big| \le 2 {L_{\nabla g}} \widebar{L}_\varPsi^2 Q$.
\label{l:QG_delta_theta}
\end{lemma}

\begin{proof}
In view of \eqref{delta0-theta},  $\Delta^0_\theta = \Eb\big[ \varPsi_\theta H(\varPsi)(F-\varPsi)\big]$. By virtue of Assumption (A2), $\|H(\varPsi)\| \le L_{\nabla g}$.
Also,
$Q_\theta = \Eb\big[ \varPsi_\theta(F-\varPsi)\big]$.
Using the Cauchy--Schwartz inequality,
we obtain the following chain of estimates:
\begin{align*}
\big|\langle \Delta^0_\theta, Q_\theta \rangle\big|  &\le \| \Delta^0_\theta\| \| Q_\theta \|
\le {L_{\nabla g}} \Eb[\|\varPsi_\theta\|^2] \Eb[\|F - \varPsi\|^2] \le 2 {L_{\nabla g}} \widebar{L}_\varPsi^2 Q.
\end{align*}
The last inequality uses \eqref{te:Q}.
\end{proof}

\begin{lemma}
Under Assumption \textup{(A3)},  $\|Q_\beta\|^2 \le 2 \widebar{L}_f^2 Q$.
\label{l:QG_Q_beta}
\end{lemma}

\begin{proof}
By the  Cauchy--Schwartz inequality,

\[
\|Q_\beta\| = \big\|\Eb[ F_\beta(F-\varPsi)]\big\| \le \sqrt{\Eb[\|F_\beta\|^2]}\sqrt{ \Eb[\|F-\varPsi\|^2]} \le  \widebar{L}_f \sqrt{2 Q}.
\]
\end{proof}

\begin{lemma}
Under Assumptions \textup{(A2)} and \textup{(A3)}, $\|\Delta^0_\beta\|^2 \le 2 L_{\nabla g}^2 \widebar{L}_f^2 Q$.
\label{l:QG_delta_beta}
\end{lemma}

\begin{proof}
By \eqref{delta0-beta}, $\Delta^0_\beta = \Eb[F_\beta(\nabla g(F) - \nabla g(\varPsi))$.
Similar to the proof of Lemma \ref{l:QG_Q_beta}, by the Cauchy--Schwartz inequality and Assumption (A2),
\begin{align*}
\|\Delta^0_\beta\|^2 &= \big\|\Eb[F_\beta(\nabla g(F) - \nabla g(\varPsi)) ]\big\|^2
\le \Eb[\|F_\beta\|^2]\, \Eb[\|\nabla g(F) - \nabla g(\varPsi)\|^2]  \\
&\le L_{\nabla g}^2 \Eb[\|F_\beta\|^2]\, \Eb[\|F - \varPsi\|^2]
\le 2L_{\nabla g}^2 \widebar{L}_f^2 Q.
\end{align*}
The last inequality uses Assumption (A3), as in Lemma \ref{l:QG_Q_beta}.
\end{proof}

\begin{proposition}
Under assumptions \textup{(A2)} and \textup{(A3)},
\[
\langle w_\beta, \dt{\beta} \rangle \le \frac{\widebar{L}_f^2}{2} \big( (\alpha+1){L_{\nabla g}} + \alpha \lambda \big)^2 Q.
\]
Furthermore, if $Q=0$, then
\[
\langle w_\beta, \dt{\beta} \rangle = - \big\| \varPi_{\Tc_{\Bb}(\beta)}\big(-G_\beta \big)\big\|^2.
\]
\label{p:QG_L_delta_Q_beta}
\end{proposition}

\begin{proof}
The first coordinate of the differential inclusion \eqref{diff-inc-beta} reads:
\begin{equation}
\dt{\beta} \in \varPi_{\Tc_{\Bb}(\beta)}\big(-\Eb[F_\beta \nabla g(\varPsi) ] \big) = \varPi_{\Tc_{\Bb}(\beta)}\big( -G_\beta + \Delta^{0}_\beta \big),
\label{grad:beta}
\end{equation}
For any solution $(\beta(t), \theta(t))$ of the inclusion \eqref{t:diff-inc-beta}, with the corresponding element $N(t) \in \Nc_{\Bb}(\beta(t))$, we define the projection matrix
\[
P(t)  = I - \frac{N(t) N(t)^T}{\|N(t)\|^2}.
\]
Then
\begin{equation}
\dt{\beta} = P (-G_\beta + \Delta^{0}_\beta).
\label{grad:beta_proj}
\end{equation}
Using the facts that $P$ is nonexpansive, $P^T=P$, and $P^2=P$,
by elementary manipulations, we obtain an upper bound:
\begin{equation}
\label{w-dot-chain}
\begin{aligned}
\lefteqn{\langle w_\beta, \dt{\beta} \rangle = -\langle G_\beta + \alpha \Delta^{\lambda}_\beta, P(G_\beta - \Delta^{0}_\beta) \rangle} \\
&= -\Big\|P\big(G_\beta + \frac{\alpha}{2} \Delta^{\lambda}_\beta - \frac{1}{2} \Delta^0_\beta\big)\Big\|^2 + \Big\|P\big(\frac{\alpha}{2} \Delta^{\lambda}_\beta + \frac{1}{2} \Delta^0_\beta\big)\Big\|^2 \\
&\le \Big\|P\big(\frac{\alpha}{2} \Delta^{\lambda}_\beta + \frac{1}{2} \Delta^0_\beta\big) \Big\|^2 =
\Big\|P\big(\frac{\alpha+1}{2} \Delta^0_\beta + \frac{\alpha \lambda}{2} Q_\beta\big)\Big\|^2 \\
&= \Big\|\frac{\alpha+1}{2} P \Delta^0_\beta\Big\|^2 + \Big\|\frac{\alpha \lambda}{2} P Q_\beta\Big\|^2 + 2 \Big\langle \rho \frac{\alpha+1}{2} P \Delta^0_\beta, \varrho^{-1} \frac{\alpha \lambda}{2} P Q_\beta \Big\rangle\\
&\le \frac{(\alpha+1)^2}{4} (1+\rho^2)\|P \Delta^0_\beta\|^2 + \frac{\alpha^2 \lambda^2}{4}(1+\rho^{-2})\|P Q_\beta\|^2,
\end{aligned}
\end{equation}
for any $\rho>0$.
Lemmas \ref{l:QG_Q_beta} and \ref{l:QG_delta_beta} allow us to continue the last estimate as follows:
\begin{align*}
\langle w_\beta, \dt{\beta} \rangle &\le \min_{\rho > 0} \Big[ \frac{(\alpha+1)^2}{4} (1+\rho^2)\|P \Delta^0_\beta\|^2 + \frac{\alpha^2 \lambda^2}{4}(1+\rho^{-2})\|P Q_\beta\|^2 \Big] \\
&\le \min_{\rho > 0} \Big[ \frac{(\alpha+1)^2}{4} (1+\rho^2)\|\Delta^0_\beta\|^2 + \frac{\alpha^2 \lambda^2}{4}(1+\rho^{-2})\|Q_\beta\|^2 \Big] \\
&\le \min_{\rho > 0} \Big[ \frac{(\alpha+1)^2}{2} (1+\rho^2) L_{\nabla g}^2 + \frac{\alpha^2 \lambda^2}{2}(1+\rho^{-2}) \Big]   \widebar{L}_f^2 Q \\
&= \frac{\widebar{L}_f^2}{2} \big( (\alpha+1){L_{\nabla g}} + \alpha \lambda \big)^2 Q.
\end{align*}
This proves the first assertion.
\begin{comment}
\begin{align*}
\langle w_\beta, \dt{\beta} \rangle &= -\langle G_\beta + \alpha \Delta^{\lambda}_\beta, P(G_\beta - \Delta^{0}_\beta) \rangle \\
&= -\Big\|G_\beta + \frac{\alpha}{2} \Delta^{\lambda}_\beta - \frac{1}{2} \Delta^0_\beta\Big\|_P^2 + \Big\|\frac{\alpha}{2} \Delta^{\lambda}_\beta + \frac{1}{2} \Delta^0_\beta\Big\|_P^2 \\
&\le \Big\|\frac{\alpha}{2} \Delta^{\lambda}_\beta + \frac{1}{2} \Delta^0_\beta\Big\|_P^2 =
\Big\|\frac{\alpha+1}{2} \Delta^0_\beta + \frac{\alpha \lambda}{2} Q_\beta\Big\|_P^2 \\
&= \Big\|\frac{\alpha+1}{2} \Delta^0_\beta\Big\|_P^2 + \Big\|\frac{\alpha \lambda}{2} Q_\beta\Big\|_P^2 + 2 \Big\langle \rho \frac{\alpha+1}{2} \Delta^0_\beta, \varrho^{-1} \frac{\alpha \lambda}{2} P Q_\beta \Big\rangle \\
&\le \min_{\rho > 0} \Big[ \frac{(\alpha+1)^2}{4} (1+\rho^2)\|\Delta^0_\beta\|_P^2 + \frac{\alpha^2 \lambda^2}{4}(1+\rho^{-2})\|Q_\beta\|_P^2 \Big] \\
&\le \min_{\rho > 0} \Big[ \frac{(\alpha+1)^2}{4} (1+\rho^2)\|\Delta^0_\beta\|^2 + \frac{\alpha^2 \lambda^2}{4}(1+\rho^{-2})\|Q_\beta\|^2 \Big] \\
&\le \min_{\rho > 0} \Big[ \frac{(\alpha+1)^2}{2} (1+\rho^2) {L_{\nabla g}}^2 + \frac{\alpha^2 \lambda^2}{2}(1+\rho^{-2}) \Big]   \widebar{L}_f^2 M \|Q_\theta\|^2 \\
&= \frac{\widebar{L}_f^2 M}{2} \big( (\alpha+1){L_{\nabla g}} + \alpha \lambda \big)^2 \|Q_\theta\|^2.
\end{align*}
\end{comment}
Now, suppose $Q=0$. This implies that $\varDelta^\lambda=0$ for all $\lambda \ge 0$.
The first line of \eqref{w-dot-chain} yields
\[
\langle w_\beta, \dt{\beta} \rangle = - \| P G_\beta \|^2 = - \big\| \varPi_{\Tc_{\Bb}(\beta)}\big(-G_\beta \big)\big\|^2,
\]
as claimed.
\end{proof}

The second coordinate of the differential inclusion \eqref{diff-inc-beta} reads:
\begin{equation}
\dt{\theta} =  \varPi_{\Tc_{\Theta_R}(\theta)}\big(\gamma\, \Eb[(F - \varPsi)^T \varPsi_\theta] \big)
= \varPi_{\Tc_{\Theta_R}(\theta)}\big( -\gamma Q_\theta\big) = -\gamma Q_\theta,
\label{grad:simp}
\end{equation}
because, by virtue of  Assumption (A6), when $\|\theta\|=R$, then $ -\gamma Q_\theta \in \Tc_{\Theta_R}(\theta)$.


\begin{theorem}
\label{t:negative-der}
Under Assumptions \textup{(A1)--(A6)}, if
\begin{equation}
\label{negative-der}
\lambda > 2 \widebar{L}_\varPsi^2 M {L_{\nabla g}} \quad \text{and} \quad
\gamma > \frac{\widebar{L}_f^2 M\big( (\alpha + 1){L_{\nabla g}} + \alpha \lambda \big)^2}{2 \alpha \big(\lambda - 2 \widebar{L}_\varPsi^2 M {L_{\nabla g}} \big)} ,
\end{equation}
then $\dt{W} \le 0$. Furthermore, $\dt{W} < 0$ if $(\beta,\theta)\notin \Zb^*$.
\end{theorem}

\begin{proof}
Following \eqref{grad:P}, \eqref{grad:simp}, Lemma \ref{l:QG_delta_theta}, and Proposition \ref{p:QG_L_delta_Q_beta},
\begin{align*}
\dt{W}
&\le \frac{\widebar{L}_f^2}{2} \big( (\alpha+1){L_{\nabla g}} + \alpha \lambda \big)^2 Q - \alpha \gamma \langle \Delta^{\lambda}_\theta, Q_\theta \rangle \\
&= \frac{\widebar{L}_f^2}{2} \big( (\alpha+1){L_{\nabla g}} + \alpha \lambda \big)^2 Q - \alpha \gamma \big[\langle \Delta^0_\theta, Q_\theta \rangle + \lambda \|Q_\theta\|^2 \big] \\
&\le \frac{\widebar{L}_f^2}{2} \big( (\alpha+1){L_{\nabla g}} + \alpha \lambda \big)^2 Q + \alpha \gamma |\langle \Delta^0_\theta, Q_\theta \rangle| - \alpha \gamma \lambda \|Q_\theta\|^2 \\
&\le \Big[\frac{\widebar{L}_f^2}{2} \big( (\alpha+1){L_{\nabla g}} + \alpha \lambda \big)^2 + \alpha \gamma \cdot 2{L_{\nabla g}} \widebar{L}_\varPsi^2 - \frac{\alpha \gamma \lambda}{M} \Big] Q \\
&= \frac{1}{M} \Big[\frac{\widebar{L}_f^2 M}{2} \big( (\alpha+1){L_{\nabla g}} + \alpha \lambda \big)^2 - \alpha \gamma \big(\lambda  - 2 \widebar{L}_\varPsi^2 M{L_{\nabla g}} \big) \Big] Q \le 0.
\end{align*}
This verifies the first assertion.
Now, suppose $\dt{W}=0$. It follows from the last inequality that $Q=0$. Then, Proposition \ref{p:QG_L_delta_Q_beta} implies that
\[
\varPi_{\Tc_{\Bb}(\beta)}\big(-G_\beta \big) = 0
\]
for some $G_\beta \in \hat{\partial}{G}(\beta)$. Consequently, using the decomposition into the projections on polar cones,
we obtain
\[
-G_\beta = \varPi_{\Tc_{\Bb}(\beta)}\big(-G_\beta \big) + \varPi_{\Nc_{\Bb}(\beta)}\big(-G_\beta \big) =
\varPi_{\Nc_{\Bb}(\beta)}\big(-G_\beta \big).
\]
This means that the optimality condition \eqref{optimality} is satisfied.
\end{proof}

\begin{proof}
The proof follows the steps of the proofs of \cite[Thm. 3.20]{duchi2018stochastic} or \cite[Thm. 3.5]{majewski2018analysis} {  or \cite{nurminskii1972convergence}}.
We provide a short outline here, for the convenience of the Reader. For brevity, we omit the
argument $\omega$, but we stress that we consider a particular path of the method.

Define
\[
\underline{w} = \liminf_{k \to \infty^{\phantom{|}}} w(z^k), \qquad \overline{w} = \limsup_{k \to \infty}w(z^k).
\]
Suppose $\underline{w} < \overline{w}$. By Assumption (A7), a value ${v}\in
(\underline{w},\overline{w})$ exists,
such that ${v} \notin G(\Bb^*)$. Take any $u \in ({v},\overline{w})$.
Define $L_1=\min\big\{k : w(z^k) \le {v} \big\}$ and for
$j=1,2,\dots$
\begin{align*}
\ell_j &= \min\big\{k\ge L_j : w(z^k) > u \big\},\\
L_{j+1} &= \min\big\{k\ge \ell_j : w(z^k) \le {v} \big\}.\\
\intertext{Then we define}
k_j &= \max\big\{ k\in [L_j,\ell_j]: w(z^k) \le {v} \big\}, \quad j=1,2,\dots.
\end{align*}
Both $k_j\to \infty$ and $\ell_j\to \infty$, as $j\to \infty$.

Consider the sums
$T_j = \sum_{k=k_j}^{\ell_j-1} \tau_k$. Due to the equicontinuity of the functions
 $w(Z_j(\Cdot))$, a constant $T >0$ exists, such that $T_j\ge T$ for all sufficiently
large $j$. Set $s_j=t_{k_j}$ in \eqref{Z-shifted} and consider the interval $[0,T]$.
By Theorem \ref{t:diff-inc-beta}, a subsequence of the sequence $\{Z_j(\Cdot)\}$ is convergent to a solution $Z_\infty(\Cdot)$ of the differential
inclusion \eqref{diff-inc-beta}. For simplicity, we still denote it by $\{Z_j(\Cdot)\}$. As $W(\Cdot)$ is absolutely continuous,
\begin{equation}
\label{gradient-desc-cont}
w(Z_\infty(T)) = w(Z_\infty(0)) + \int_0^T  \dt{W}(t)  \;\D t.
\end{equation}
Since ${v} \notin w(\Zb^*)$, then  $Z_\infty(0) = \lim_{j\to \infty} z^{k_j} \notin \Zb^*$.
Theorem \ref{t:negative-der} then implies that $\dt{W}(0)<0$.
The generalized subdifferential $\hat{\partial} G(\Cdot)$ and the normal cone $\Nc_\Bb(\Cdot)$ are upper semicontinuous and closed-valued. The function $Q(\Cdot,\Cdot)$ is continuous.
Therefore, $\dt{W}(t)<0$
 in some interval $t\in [0,\bar{t}\,]$ of positive length.

 It follows from \eqref{gradient-desc-cont}
 that $w(Z_\infty(T)) < w(Z_\infty(0)) =v$.
 However, $Z_\infty(T)$ is the limit of the sequence $\{z^{m_j}\}$, where
\begin{equation}
\label{mj}
m_j = \min\bigg\{m \ge k_j: \sum_{k=k_j}^{m_j-1}\tau_k \ge T\bigg\}, \quad j=1,2,\dots.
\end{equation}
For all sufficiently large $j$ we  have $k_j \le m_j \le \ell_j$ and $w(z^{m_j}) > v$, which is a contradiction. Therefore,
$\underline{w} = \overline{w}$ and the sequence $\big\{w(z^k)\big\}$ has a limit.

Suppose a subsequence $\{z^{k_j}\}$ is convergent to a point $\bar{z}\notin \Zb^*$. Again, we
set $s_j = t_{k_j}$ in \eqref{Z-shifted}, consider the interval $[0,T]$ with $T>0$, and conclude that
a  sub-subsequence of $\{Z_j(\Cdot)\}$ exists, which is uniformly convergent to a solution $Z_\infty(\Cdot)$ of the
differential inclusion \eqref{diff-inc-beta}. Then the points $\{z^{m_j}\}$ are convergent to $Z_\infty(T)$ on this sub-subsequence,
where $m_j$ are defined as in \eqref{mj}.
As $Z_\infty(0)=\bar{z}\notin \Zb^*$, we obtain $Z_\infty(T)< Z_\infty(0)$. This would mean that a sub-subsequence
of $\big\{w(z^{m_j})\big\}$ has the limit $w(Z_\infty(T))< w(\bar{z})$, which contradicts the convergence of the sequence
$\big\{w(z^{k})\big\}$.
\end{proof}

