\begin{lemma}
\label{l:conditional_subgradient}
Suppose the function $f(X,Y,\Cdot)$ is differentiable in the generalized sense and its subgradients are bounded
by an integrable function in any bounded neighborhood of any point $\beta$. Then for almost all $X$ the function
$\beta \mapsto \Eb\big[ f(X,Y,\beta) \big| X\big]$ is differentiable in the generalized sense, and
for every measurable function $s:\Rb^{n_x}\times \Rb^{n_y} \to \Rb^{n_f}$ such that $s(X,Y)  \in \hat{\partial}_\beta f(X,Y,\beta)$ a.s., we have
\[
\Eb\big[s(X,Y) \big| X\big] \in \hat{\partial} \Eb\big[ f(X,Y,\beta) \big| X\big] \quad  a.s.
\]
\end{lemma}

Furthermore, by Theorem \ref{t:composition} and Assumption (A2), the composition
$g( F(x,\Cdot))$ is differentiable in the generalized sense as well, and
\[
\hat{\partial}_{  \beta} [g\circ F](x,\beta)  = \big\{    F_\beta(x,\beta) \nabla g(F(x,\beta)) : F_\beta(x,\beta) \in \hat{\partial}_{  \beta} F (x,\beta)\big\}
\]
is its generalized subdifferential (we adopt the convention that the generalized Jacobian $F_\beta$ is an $n_\beta \times n_f$ matrix).
Thanks to the integrability condition in (A3) and Theorem \ref{t:expected-generalized}, the function $G(\Cdot)$ in \eqref{cso}
is differentiable in the generalized sense as well, and a realization of its generalized subdifferential is the multifunction
\begin{equation}
    \label{G-sub}
\begin{aligned}
\hat{\partial}_{  \beta} G(\beta) &= \Eb \big\{ \hat{\partial}_{  \beta} [g\circ F](X,\beta) \big\}
=\Eb \big\{
\hat{\partial}_{  \beta} F (X,\beta) \nabla g(F(X,\beta))
\big\}
\\ &= \Eb \big\{
\hat{\partial}f (X,Y,\beta) \nabla g(F(X,\beta))
\big\}.
\end{aligned}
\end{equation}
The last equation follows by conditioning.

Due to Assumptions (A3) and (A4), by virtue of Theorem \ref{t:composition},
the error function \eqref{te:Q} is differentiable in the generalized sense as well, and
the multifunction
\begin{equation}
\label{dQ}
\hat{\partial}_{(\beta,\theta)} Q(\beta,\theta) =
\Eb\left\{ \begin{bmatrix}
\hat{\partial}_{  \beta} f(X,Y,\beta) \\
-\hat{\partial}_{  \theta} \varPsi(X,\theta)
\end{bmatrix}
 \big(   F(X, \beta) - \varPsi(X, \theta)\big) \right\}
\end{equation}
is its generalized subdifferential.
%Evidently, we cannot observe unbiased estimates of the subgradients of $Q(\Cdot,\Cdot)$, because we do not see $F(X,\beta)$.
Since the set \eqref{dQ} is a Cartesian product, its $\theta$-part,
\[
\hat{\partial}_{\theta} Q(\beta,\theta) =
- \Eb\left\{
\hat{\partial}_{  \theta} \varPsi(X,\theta)
 \big(   F(X, \beta) - \varPsi(X, \theta)\big) \right\},
\]
is a subdifferential of $Q(\beta,\theta)$ with respect to $\theta$.

\begin{lemma}
\label{l:Gamma}
The multifunction $\varGamma(\Cdot,\Cdot)$ is nonempty-, convex-, and compact-valued and upper-semicontinuous.
\end{lemma}

\begin{lemma}
\label{l:dk-in-Gamma}
For all $k=0,1,2,\dots$ we have $d^k \in \varGamma(\beta^k,\theta^k)$.
\end{lemma}

\begin{proof}
Since the observation $(X^k,Y^k)$ is independent of $\Fc_k$, Lemma \ref{l:conditional_subgradient}  yields the relations
\begin{align*}
\Eb[\tilde{d}_\beta^k|\Fc_k]  &\in -\Eb \big[ \hat{\partial}_{ \beta} f(X^k,Y^k,\beta^k) \nabla g(\varPsi(X^k,\theta^k)) ~\big|~ \Fc_k\big] \\
&= -\Eb \Big\{ \Eb \big[ \hat{\partial}_{ \beta} f(X^k,Y^k,\beta^k)  ~\big|~ \beta^k,\theta^k, X^k \big] \nabla g(\varPsi(X^k,\theta^k)) ~\Big|~ \beta^k,\theta^k \Big\}\\
&= -\Eb \big[ \hat{\partial}_{ \beta} F(X^k,\beta^k) \nabla g(\varPsi(X^k,\theta^k)) ~\big|~ \beta^k,\theta^k \big]
= \varGamma_\beta (\beta^k,\theta^k).
\end{align*}
The $\theta$-component of the direction can also be treated by conditioning:
\begin{align*}
\Eb[\tilde{d}_\theta^k|\Fc_k] &\in \gamma \Eb \big[ \hat{\partial}_{ \theta} \varPsi(X^k,\theta^k)\big(f(X^k,Y^k,\beta^k) -\varPsi(X^k,\theta^k)\big)\big| \Fc_k\big]\\
&= \gamma \Eb \Big\{\hat{\partial}_{ \theta} \varPsi(X^k,\theta^k)\Eb\big[f(X^k,Y^k,\beta^k) -\varPsi(X^k,\theta^k)\big| X^k,\beta^k,\theta^k\big]\Big| \beta^k,\theta^k\Big\}\\
&= \gamma \Eb \big\{\hat{\partial}_{ \theta} \varPsi(X^k,\theta^k)\big(F(X^k,\beta^k) -\varPsi(X^k,\theta^k)\big)\big| \beta^k,\theta^k\big\} = \varGamma_\theta(\beta^k,\theta^k).
\end{align*}
\end{proof}

\begin{lemma}
    \label{l:e2-bounded}
Under Assumptions \textup{(A1)--(A4)}, the directions $\{d^k\}_{k\ge 0}$ are well-defined and a constant $\sigma > 0$ exists, such that
$\Eb\big[\|e^k\|^2 \,\big|\,\Fc_k\big] \le \sigma^2$, for all $k \ge 0$.
\end{lemma}

The following theorem follows directly from \cite[Thm. 4.1]{majewski2018analysis}.
\begin{theorem}
\label{t:diff-inc-beta}
Under Assumptions \textup{(A1)--(A4)} and \textup{(A7)},
the sequence $\big\{Z_m(\Cdot)\big\}_{m\ge 0}$ has a subsequence convergent a.s. to an absolutely continuous function $Z_\infty:[0,\infty) \to \Xc$ which is a solution of the differential inclusion:
\begin{equation}
\label{diff-inc-beta}
\dt{Z}_\infty(t) \in  \varGamma(Z_{\infty}(t))-\Nc_{\Zb}(Z_\infty(t)), \quad t \ge 0.
\end{equation}
Moreover, for any $t\ge 0$, the point $Z_\infty(t)$
is an accumulation point of the sequence $\{z^k\}_{k\ge 0}$.
\end{theorem}

Since any solution of \eqref{diff-inc-beta} must lie in $\Zb$,
we can  write the differential inclusion \eqref{diff-inc-beta} in an equivalent way \cite{aubin2012differential}:
\begin{equation}
\label{diff-inc-beta-T}
\dt{Z}_\infty(t) \in \varPi_{\Tc_{\Zb}(Z_\infty(t))}\big( \varGamma(Z_\infty(t))\big), \quad t \ge 0,
\end{equation}
which underlines the nature of the limiting subgradient process. Here, $\Tc_\Zb(z)$ is the tangent cone to the convex set $\Zb$ at $z$.

\begin{lemma}
\label{l:w-gendif}
Under Assumptions \textup{(A2)--(A4)} the Lyapunov function $w(\Cdot,\Cdot)$ is differentiable in the generalized sense.
\end{lemma}

Following the differential inclusion method, consider the function $W(t) = w(\beta(t),\theta(t))$, $t \ge 0$, where $(\beta(\Cdot),\theta(\Cdot)) \triangleq Z(\Cdot)$ is a solution of the
inclusion \eqref{diff-inc-beta}.

As the Lyapunov function $w(\Cdot,\Cdot)$ is Norkin differentiable, by virtue of Theorem \ref{t:composition}, its
weak derivative can be expressed by the chain rule:
\begin{equation}
\dt{W}
= \langle w_\beta, \dt{\beta} \rangle + \langle w_\theta, \dt{\theta} \rangle
= \langle G_\beta + \alpha \Delta^\lambda_\beta, \dt{\beta} \rangle + \alpha \langle \Delta^\lambda_\theta, \dt{\theta} \rangle.
\label{grad:P}
\end{equation}
Due to Theorem \ref{t:chain}, the integral  $\int_0^T \dt{W}(t)\,\D t$ on any interval of time does not depend on the particular selections of the generalized subgradients used in this calculation.

\begin{lemma}
Under Assumptions \textup{(A2)} and \textup{(A4)},  $\big|\langle \Delta^0_\theta, Q_\theta \rangle \big| \le 2 {L_{\nabla g}} \widebar{L}_\varPsi^2 Q$.
\label{l:QG_delta_theta}
\end{lemma}

\begin{proof}
In view of \eqref{delta0-theta},  $\Delta^0_\theta = \Eb\big[ \varPsi_\theta H(\varPsi)(F-\varPsi)\big]$. By virtue of Assumption (A2), $\|H(\varPsi)\| \le L_{\nabla g}$.
Also,
$Q_\theta = \Eb\big[ \varPsi_\theta(F-\varPsi)\big]$.
Using the Cauchy--Schwartz inequality,
we obtain the following chain of estimates:
\begin{align*}
\big|\langle \Delta^0_\theta, Q_\theta \rangle\big|  &\le \| \Delta^0_\theta\| \| Q_\theta \|
\le {L_{\nabla g}} \Eb[\|\varPsi_\theta\|^2] \Eb[\|F - \varPsi\|^2] \le 2 {L_{\nabla g}} \widebar{L}_\varPsi^2 Q.
\end{align*}
The last inequality uses \eqref{te:Q}.
\end{proof}

\begin{lemma}
Under Assumption \textup{(A3)},  $\|Q_\beta\|^2 \le 2 \widebar{L}_f^2 Q$.
\label{l:QG_Q_beta}
\end{lemma}

\begin{proof}
By the  Cauchy--Schwartz inequality,

\[
\|Q_\beta\| = \big\|\Eb[ F_\beta(F-\varPsi)]\big\| \le \sqrt{\Eb[\|F_\beta\|^2]}\sqrt{ \Eb[\|F-\varPsi\|^2]} \le  \widebar{L}_f \sqrt{2 Q}.
\]
\end{proof}

\begin{lemma}
Under Assumptions \textup{(A2)} and \textup{(A3)}, $\|\Delta^0_\beta\|^2 \le 2 L_{\nabla g}^2 \widebar{L}_f^2 Q$.
\label{l:QG_delta_beta}
\end{lemma}

\begin{proof}
By \eqref{delta0-beta}, $\Delta^0_\beta = \Eb[F_\beta(\nabla g(F) - \nabla g(\varPsi))$.
Similar to the proof of Lemma \ref{l:QG_Q_beta}, by the Cauchy--Schwartz inequality and Assumption (A2),
\begin{align*}
\|\Delta^0_\beta\|^2 &= \big\|\Eb[F_\beta(\nabla g(F) - \nabla g(\varPsi)) ]\big\|^2
\le \Eb[\|F_\beta\|^2]\, \Eb[\|\nabla g(F) - \nabla g(\varPsi)\|^2]  \\
&\le L_{\nabla g}^2 \Eb[\|F_\beta\|^2]\, \Eb[\|F - \varPsi\|^2]
\le 2L_{\nabla g}^2 \widebar{L}_f^2 Q.
\end{align*}
The last inequality uses Assumption (A3), as in Lemma \ref{l:QG_Q_beta}.
\end{proof}

\begin{proof}
The first coordinate of the differential inclusion \eqref{diff-inc-beta} reads:
\begin{equation}
\dt{\beta} \in \varPi_{\Tc_{\Bb}(\beta)}\big(-\Eb[F_\beta \nabla g(\varPsi) ] \big) = \varPi_{\Tc_{\Bb}(\beta)}\big( -G_\beta + \Delta^{0}_\beta \big),
\label{grad:beta}
\end{equation}
For any solution $(\beta(t), \theta(t))$ of the inclusion \eqref{t:diff-inc-beta}, with the corresponding element $N(t) \in \Nc_{\Bb}(\beta(t))$, we define the projection matrix
\[
P(t)  = I - \frac{N(t) N(t)^T}{\|N(t)\|^2}.
\]
Then
\begin{equation}
\dt{\beta} = P (-G_\beta + \Delta^{0}_\beta).
\label{grad:beta_proj}
\end{equation}
Using the facts that $P$ is nonexpansive, $P^T=P$, and $P^2=P$,
by elementary manipulations, we obtain an upper bound:
\begin{equation}
\label{w-dot-chain}
\begin{aligned}
\lefteqn{\langle w_\beta, \dt{\beta} \rangle = -\langle G_\beta + \alpha \Delta^{\lambda}_\beta, P(G_\beta - \Delta^{0}_\beta) \rangle} \\
&= -\Big\|P\big(G_\beta + \frac{\alpha}{2} \Delta^{\lambda}_\beta - \frac{1}{2} \Delta^0_\beta\big)\Big\|^2 + \Big\|P\big(\frac{\alpha}{2} \Delta^{\lambda}_\beta + \frac{1}{2} \Delta^0_\beta\big)\Big\|^2 \\
&\le \Big\|P\big(\frac{\alpha}{2} \Delta^{\lambda}_\beta + \frac{1}{2} \Delta^0_\beta\big) \Big\|^2 =
\Big\|P\big(\frac{\alpha+1}{2} \Delta^0_\beta + \frac{\alpha \lambda}{2} Q_\beta\big)\Big\|^2 \\
&= \Big\|\frac{\alpha+1}{2} P \Delta^0_\beta\Big\|^2 + \Big\|\frac{\alpha \lambda}{2} P Q_\beta\Big\|^2 + 2 \Big\langle \rho \frac{\alpha+1}{2} P \Delta^0_\beta, \varrho^{-1} \frac{\alpha \lambda}{2} P Q_\beta \Big\rangle\\
&\le \frac{(\alpha+1)^2}{4} (1+\rho^2)\|P \Delta^0_\beta\|^2 + \frac{\alpha^2 \lambda^2}{4}(1+\rho^{-2})\|P Q_\beta\|^2,
\end{aligned}
\end{equation}
for any $\rho>0$.
Lemmas \ref{l:QG_Q_beta} and \ref{l:QG_delta_beta} allow us to continue the last estimate as follows:
\begin{align*}
\langle w_\beta, \dt{\beta} \rangle &\le \min_{\rho > 0} \Big[ \frac{(\alpha+1)^2}{4} (1+\rho^2)\|P \Delta^0_\beta\|^2 + \frac{\alpha^2 \lambda^2}{4}(1+\rho^{-2})\|P Q_\beta\|^2 \Big] \\
&\le \min_{\rho > 0} \Big[ \frac{(\alpha+1)^2}{4} (1+\rho^2)\|\Delta^0_\beta\|^2 + \frac{\alpha^2 \lambda^2}{4}(1+\rho^{-2})\|Q_\beta\|^2 \Big] \\
&\le \min_{\rho > 0} \Big[ \frac{(\alpha+1)^2}{2} (1+\rho^2) L_{\nabla g}^2 + \frac{\alpha^2 \lambda^2}{2}(1+\rho^{-2}) \Big]   \widebar{L}_f^2 Q \\
&= \frac{\widebar{L}_f^2}{2} \big( (\alpha+1){L_{\nabla g}} + \alpha \lambda \big)^2 Q.
\end{align*}
This proves the first assertion.
\begin{comment}
\begin{align*}
\langle w_\beta, \dt{\beta} \rangle &= -\langle G_\beta + \alpha \Delta^{\lambda}_\beta, P(G_\beta - \Delta^{0}_\beta) \rangle \\
&= -\Big\|G_\beta + \frac{\alpha}{2} \Delta^{\lambda}_\beta - \frac{1}{2} \Delta^0_\beta\Big\|_P^2 + \Big\|\frac{\alpha}{2} \Delta^{\lambda}_\beta + \frac{1}{2} \Delta^0_\beta\Big\|_P^2 \\
&\le \Big\|\frac{\alpha}{2} \Delta^{\lambda}_\beta + \frac{1}{2} \Delta^0_\beta\Big\|_P^2 =
\Big\|\frac{\alpha+1}{2} \Delta^0_\beta + \frac{\alpha \lambda}{2} Q_\beta\Big\|_P^2 \\
&= \Big\|\frac{\alpha+1}{2} \Delta^0_\beta\Big\|_P^2 + \Big\|\frac{\alpha \lambda}{2} Q_\beta\Big\|_P^2 + 2 \Big\langle \rho \frac{\alpha+1}{2} \Delta^0_\beta, \varrho^{-1} \frac{\alpha \lambda}{2} P Q_\beta \Big\rangle \\
&\le \min_{\rho > 0} \Big[ \frac{(\alpha+1)^2}{4} (1+\rho^2)\|\Delta^0_\beta\|_P^2 + \frac{\alpha^2 \lambda^2}{4}(1+\rho^{-2})\|Q_\beta\|_P^2 \Big] \\
&\le \min_{\rho > 0} \Big[ \frac{(\alpha+1)^2}{4} (1+\rho^2)\|\Delta^0_\beta\|^2 + \frac{\alpha^2 \lambda^2}{4}(1+\rho^{-2})\|Q_\beta\|^2 \Big] \\
&\le \min_{\rho > 0} \Big[ \frac{(\alpha+1)^2}{2} (1+\rho^2) {L_{\nabla g}}^2 + \frac{\alpha^2 \lambda^2}{2}(1+\rho^{-2}) \Big]   \widebar{L}_f^2 M \|Q_\theta\|^2 \\
&= \frac{\widebar{L}_f^2 M}{2} \big( (\alpha+1){L_{\nabla g}} + \alpha \lambda \big)^2 \|Q_\theta\|^2.
