\begin{theorem}
    \label{t:full-convergence}
    Assume conditions {\rm (A1)--(A8)} and \eqref{negative-der}. Then, except for a zero measure set $\varOmega_0\subset \varOmega$,  the sequence $\big\{w(z^k(\omega))\big\}_{k\in \Nb}$ is convergent, and every accumulation point of the sequence
$\big\{z^k(\omega)\big\}_{k\in \Nb}$ is an element of $\Zb^*$.
\end{theorem}

The \emph{Conditional Stochastic Optimization} (CSO) problem is formulated as follows:
\begin{equation}
\min_{\beta \in {\Bb}} G(\beta) \triangleq \Eb \Big\{g\big(\Eb [f(X,Y,\beta) \,|\, X]\big)\Big\}
\label{cso}
\end{equation}

\begin{equation}
    \label{def:F}
F(X, \beta) \triangleq \Eb[f(X, Y, \beta) | X].
\end{equation}

We assume that a sufficiently rich class of functions $\varPsi: \Rb^{n_x} \times \Rb^{n_\theta} \to \Rb^{n_f}$ has been established,
such that for every
$\beta\in {\Bb}$ an (unknown) value of the parameters $\bar{\theta}(\beta) \in \Rb^{n_\theta}$ exists for which
\begin{equation}
\label{tracking-exact}
F(X,\beta) = \varPsi\big(X,\bar{\theta}(\beta)\big)  \quad \text{a.s.}
\end{equation}

\begin{equation}
Q(\beta, \theta) \triangleq \frac{1}{2}
\Eb\big[\|F(X, \beta) - \varPsi(X, \theta)\|^2\big],
\label{te:Q}
\end{equation}

\item[(A3)] For every $x \in \Rb^{n_x}$ and every $y\in \Rb^{n_y}$ the function $f(x,y,\Cdot)$ is differentiable in the generalized sense
with the generalized subdifferential $\hat{\partial} f(x,y,\Cdot)$. Furthermore,  a function ${L_f}(x,y)$ and  constants $\widebar{L}_f>0$ and $C_f>0$  exist, such that
for all $\beta\in \Bb$ and all $(x,y)$
\begin{gather*}
 \sup_{f_\beta \in \hat{\partial} f(x,y,\beta)}\|f_\beta\| \le {L_f}(x,y),\\
\Eb [ {L_f}(X,Y)^4 ] \le \widebar{L}_f^4,\\
\intertext{and}
\Eb\big[\|f(X,Y,\beta)\|^4 \big] \le C_f^4.
\end{gather*}

\item[(A4)] For every $x \in \Rb^{n_x}$ the function $\varPsi(x,\Cdot)$ is differentiable in the generalized sense
with the generalized subdifferential $\hat{\partial} \varPsi(x,\Cdot)$. Furthermore, a function ${L_\psi}(x)$ and  constants
$\widebar{L}_\varPsi>0$ and  $C_{\varPsi}>0$ exist, such that for all $x$
\begin{gather*}
\sup_{\theta \in \Rb^{n_\theta}}\  \sup_{\varPsi_\theta \in \hat{\partial} \varPsi(x,\theta)}\|\varPsi_\theta\| \le {L_\psi}(x),\\
\Eb [ {L_\psi}(X)^4 ] \le \widebar{L}_\varPsi^4,\\
\intertext{and for some $\theta^0$,}
\Eb [ \|\varPsi(X,\theta^0)\|^4 ] \le C_\varPsi^4.
\end{gather*}
\end{description}

We can compactly write the assertion of the above lemma as\footnote{Here and elsewhere, the subdifferentiation is with respect to the parameters $\beta$ or $\theta$; we omit the corresponding subscripts of $\hat{\partial}$ to alleviate the notation.}
\begin{equation}
\label{dFbeta}
\hat{\partial}_{  \beta} F(X,\beta) = \Eb \big[ \hat{\partial}_{  \beta} f(X,Y,\beta)\,\big|\, X \big] \quad \text{a.s.,}
\end{equation}

The necessary optimality condition  for problem \eqref{cso} has the form
\begin{equation}
\label{optimality}
0 \in \hat{\partial}_{ \beta} G(\beta) + \Nc_{\Bb}(\beta),
\end{equation}

where $\hat{\partial}_{ \beta} G(\Cdot)$ is the generalized subdifferential \eqref{G-sub} and $\Nc_{\Bb}(\Cdot)$ is the normal cone
to the set $\Bb$. We define the sets
\begin{align*}
    {\Bb}^* &= \big\{ \beta\in {\Bb} : \ \text{\eqref{optimality} is satisfied} \big\},\\
    \Zb^* &= \big\{ (\beta,\theta)\in {\Bb}^* \times \Rb^{n_\theta}:  Q(\beta,\theta) = 0\big\}.
\end{align*}

\begin{equation}
\label{method}
\begin{aligned}
\beta^{k+1} &= \varPi_{\Bb}(\beta^k + \tau_k \tilde{d}_\beta^k),\\
\theta^{k+1} &= \varPi_{\Theta_R}(\theta^k + \tau_k \tilde{d}_\theta^k).
\end{aligned}
\end{equation}

Then we calculate the directions in \eqref{method}:
\begin{subequations}
\label{dzk}
\begin{align}
    \tilde{d}_\beta^k &= - f_\beta^k \,\nabla g^k,  \label{dbetak}\\
    \tilde{d}_\theta^k &=\gamma \,\varPsi_\theta^k (f^k - \varPsi^k). \label{dthetak}
\end{align}

\begin{description}
\item[(A7)]
The stepsizes $\tau_k$ are $\Fc_k$-measurable, and such that\vspace{0.5ex}
\begin{tightlist}{iii}
\item  $\tau_k >0, \quad k=0,1,2,\dots$;
\item   $ \displaystyle{\sum_{k=0}^\infty} \tau_k = \infty \quad \text{a.s.}$;
\item $\Eb \displaystyle{\sum_{k=0}^\infty} \tau_k^2 < \infty$.
\end{tightlist}
\end{description}

Define the average directions,
\begin{equation}
\label{def:avg_dir}
d^k = \Eb [\tilde{d}^k \,| \, \Fc_k],\quad k=0,1,\dots,
\end{equation}

and let
\begin{equation}
\notag
%\label{def:e}
e^k = \tilde{d^k} - d^k.
\end{equation}

Then, for an increasing sequence of positive numbers $\{s_m\}$ diverging to $\infty$, we define the shifted trajectories
\begin{equation}
\label{Z-shifted}
Z_m(t)=Z_0(t+s_m), \quad m=0,1,\dots,\quad t \ge 0.
\end{equation}

To this end, we construct a specially tailored Lyapunov function with parameters $\alpha > 0$ and $\lambda \ge 0$:
\begin{equation}
\label{Lyapunov}
    w(\beta,\theta) \triangleq G(\beta) + \alpha \Delta^\lambda(\beta, \theta),
\end{equation}

where $G(\beta)$ is the CSO loss function in \eqref{cso} and
\begin{equation}
\Delta^{\lambda}(\beta,\theta) \triangleq \Eb\Big[g(F) - g(\varPsi) - \langle \nabla g(\varPsi), F - \varPsi \rangle + \frac{\lambda}{2} \|F-\varPsi\|^2\Big].
\label{te:g}
\end{equation}

In order to prove the convergence of the discrete-time algorithm, we need an additional technical assumption (known as the \emph{Sard condition}).
\begin{description}
\item[(A8)] The set $\{G(\beta): \beta\in {\Bb}^*\}$ does not contain an interval of nonzero length.
\end{description}

\begin{lemma}
\label{l:conditional_subgradient}
Suppose the function $f(X,Y,\Cdot)$ is differentiable in the generalized sense and its subgradients are bounded
by an integrable function in any bounded neighborhood of any point $\beta$. Then for almost all $X$ the function
$\beta \mapsto \Eb\big[ f(X,Y,\beta) \big| X\big]$ is differentiable in the generalized sense, and
for every measurable function $s:\Rb^{n_x}\times \Rb^{n_y} \to \Rb^{n_f}$ such that $s(X,Y)  \in \hat{\partial}_\beta f(X,Y,\beta)$ a.s., we have
\[
\Eb\big[s(X,Y) \big| X\big] \in \hat{\partial} \Eb\big[ f(X,Y,\beta) \big| X\big] \quad  a.s.
\]
\end{lemma}

Furthermore, by Theorem \ref{t:composition} and Assumption (A2), the composition
$g( F(x,\Cdot))$ is differentiable in the generalized sense as well, and
\[
\hat{\partial}_{  \beta} [g\circ F](x,\beta)  = \big\{    F_\beta(x,\beta) \nabla g(F(x,\beta)) : F_\beta(x,\beta) \in \hat{\partial}_{  \beta} F (x,\beta)\big\}
\]
is its generalized subdifferential (we adopt the convention that the generalized Jacobian $F_\beta$ is an $n_\beta \times n_f$ matrix).
Thanks to the integrability condition in (A3) and Theorem \ref{t:expected-generalized}, the function $G(\Cdot)$ in \eqref{cso}
is differentiable in the generalized sense as well, and a realization of its generalized subdifferential is the multifunction
\begin{equation}
    \label{G-sub}
\begin{aligned}
\hat{\partial}_{  \beta} G(\beta) &= \Eb \big\{ \hat{\partial}_{  \beta} [g\circ F](X,\beta) \big\}
=\Eb \big\{
\hat{\partial}_{  \beta} F (X,\beta) \nabla g(F(X,\beta))
\big\}
\\ &= \Eb \big\{
\hat{\partial}f (X,Y,\beta) \nabla g(F(X,\beta))
\big\}.
\end{aligned}
\end{equation}
The last equation follows by conditioning.

Thanks to the integrability condition in (A3) and Theorem \ref{t:expected-generalized}, the function $G(\Cdot)$ in \eqref{cso}
is differentiable in the generalized sense as well, and a realization of its generalized subdifferential is the multifunction
\begin{equation}
    \label{G-sub}
\begin{aligned}
\hat{\partial}_{  \beta} G(\beta) &= \Eb \big\{ \hat{\partial}_{  \beta} [g\circ F](X,\beta) \big\}
=\Eb \big\{
\hat{\partial}_{  \beta} F (X,\beta) \nabla g(F(X,\beta))
\big\}
\\ &= \Eb \big\{
\hat{\partial}f (X,Y,\beta) \nabla g(F(X,\beta))
\big\}.
\end{aligned}
\end{equation}
The last equation follows by conditioning.

Due to Assumptions (A3) and (A4), by virtue of Theorem \ref{t:composition},
the error function \eqref{te:Q} is differentiable in the generalized sense as well, and
the multifunction
\begin{equation}
\label{dQ}
\hat{\partial}_{(\beta,\theta)} Q(\beta,\theta) =
\Eb\left\{ \begin{bmatrix}
\hat{\partial}_{  \beta} f(X,Y,\beta) \\
-\hat{\partial}_{  \theta} \varPsi(X,\theta)
\end{bmatrix}
 \big(   F(X, \beta) - \varPsi(X, \theta)\big) \right\}
\end{equation}
is its generalized subdifferential.
%Evidently, we cannot observe unbiased estimates of the subgradients of $Q(\Cdot,\Cdot)$, because we do not see $F(X,\beta)$.
Since the set \eqref{dQ} is a Cartesian product, its $\theta$-part,
\[
\hat{\partial}_{\theta} Q(\beta,\theta) =
- \Eb\left\{
\hat{\partial}_{  \theta} \varPsi(X,\theta)
 \big(   F(X, \beta) - \varPsi(X, \theta)\big) \right\},
\]
is a subdifferential of $Q(\beta,\theta)$ with respect to $\theta$.

Due to Assumptions (A3) and (A4), by virtue of Theorem \ref{t:composition},
the error function \eqref{te:Q} is differentiable in the generalized sense as well, and
the multifunction
\begin{equation}
\label{dQ}
\hat{\partial}_{(\beta,\theta)} Q(\beta,\theta) =
\Eb\left\{ \begin{bmatrix}
\hat{\partial}_{  \beta} f(X,Y,\beta) \\
-\hat{\partial}_{  \theta} \varPsi(X,\theta)
\end{bmatrix}
 \big(   F(X, \beta) - \varPsi(X, \theta)\big) \right\}
\end{equation}
is its generalized subdifferential.

\begin{lemma}
\label{l:Gamma}
The multifunction $\varGamma(\Cdot,\Cdot)$ is nonempty-, convex-, and compact-valued and upper-semicontinuous.
\end{lemma}

\begin{proof}
By virtue of Lemma \ref{l:conditional_subgradient}, the $\beta$-component of $\varGamma(\beta,\theta)$ equals
\begin{multline*}
 -\Eb \big[ \hat{\partial}_\beta F(X,\beta) \nabla g\big(\varPsi(X,\theta)\big)\big] =
 -\Eb\Big\{ \Eb\big[ \hat{\partial}_\beta f(X,Y,\beta)\big|X\big] \nabla g\big(\varPsi(X,\theta)\big)\Big\}\\
% - \hat{\partial}_\beta  \Eb \big[ F(X,\beta) \nabla g\big(\varPsi(X,\theta)\big)\big]\\
% =
% - \hat{\partial}_\beta  \Eb \big[ f(X,Y,\beta) \nabla g\big(\varPsi(X,\theta)\big)\big]
  =
 - \Eb \big[ \hat{\partial}_\beta  f(X,Y,\beta) \nabla g\big(\varPsi(X,\theta)\big)\big].
\end{multline*}
