&= -\Eb \Big\{ \Eb \big[ \hat{\partial}_{ \beta} f(X^k,Y^k,\beta^k)  ~\big|~ \beta^k,\theta^k, X^k \big] \nabla g(\varPsi(X^k,\theta^k)) ~\Big|~ \beta^k,\theta^k \Big\}\\
