\begin{theorem}
\label{t:diff-inc-beta}
Under Assumptions \textup{(A1)--(A4)} and \textup{(A7)},
the sequence $\big\{Z_m(\Cdot)\big\}_{m\ge 0}$ has a subsequence convergent a.s. to an absolutely continuous function $Z_\infty:[0,\infty) \to \Xc$ which is a solution of the differential inclusion:
\begin{equation}
\label{diff-inc-beta}
\dt{Z}_\infty(t) \in  \varGamma(Z_{\infty}(t))-\Nc_{\Zb}(Z_\infty(t)), \quad t \ge 0.
\end{equation}
Moreover, for any $t\ge 0$, the point $Z_\infty(t)$
is an accumulation point of the sequence $\{z^k\}_{k\ge 0}$.
\end{theorem}

Since any solution of \eqref{diff-inc-beta} must lie in $\Zb$,
we can  write the differential inclusion \eqref{diff-inc-beta} in an equivalent way \cite{aubin2012differential}:
\begin{equation}
\label{diff-inc-beta-T}
\dt{Z}_\infty(t) \in \varPi_{\Tc_{\Zb}(Z_\infty(t))}\big( \varGamma(Z_\infty(t))\big), \quad t \ge 0,
\end{equation}
which underlines the nature of the limiting subgradient process. Here, $\Tc_\Zb(z)$ is the tangent cone to the convex set $\Zb$ at $z$.

Since any solution of \eqref{diff-inc-beta} must lie in $\Zb$,
we can  write the differential inclusion \eqref{diff-inc-beta} in an equivalent way \cite{aubin2012differential}:
\begin{equation}
\label{diff-inc-beta-T}
\dt{Z}_\infty(t) \in \varPi_{\Tc_{\Zb}(Z_\infty(t))}\big( \varGamma(Z_\infty(t))\big), \quad t \ge 0,
\end{equation}
